class Solution:
    def countSameShape(self, words: List[str], pattern: str) -> int:
        L = len(pattern)
        total = 0
        for w in words:
            if len(w) != L:
                continue
            if all((w[i] == w[j]) == (pattern[i] == pattern[j])
                   for i in range(L) for j in range(i + 1, L)):
                total += 1
        return total

