class Solution {
    public int countSameShape(String[] words, String pattern) {
        int L = pattern.length(), total = 0;
        for (String w : words) {
            if (w.length() != L) continue;
            boolean ok = true;
            for (int i = 0; i < L && ok; i++)
                for (int j = i + 1; j < L && ok; j++)
                    ok = (w.charAt(i) == w.charAt(j)) == (pattern.charAt(i) == pattern.charAt(j));
            if (ok) total++;
        }
        return total;
    }
}

