class Solution:
    def countSameShape(self, words: List[str], pattern: str) -> int:
        total = 0
        for w in words:
            if len(w) != len(pattern):
                continue
            fwd, back = {}, {}
            ok = True
            for x, y in zip(w, pattern):
                if fwd.setdefault(x, y) != y or back.setdefault(y, x) != x:
                    ok = False
                    break
            total += ok
        return total

