class Solution {
    public int countSameShape(String[] words, String pattern) {
        int total = 0;
        for (String w : words) {
            if (w.length() != pattern.length()) continue;
            char[] fwd = new char[26], back = new char[26];
            boolean ok = true;
            for (int i = 0; i < w.length() && ok; i++) {
                char x = w.charAt(i), y = pattern.charAt(i);
                if (fwd[x - 'a'] == 0 && back[y - 'a'] == 0) {
                    fwd[x - 'a'] = y;
                    back[y - 'a'] = x;
                } else if (fwd[x - 'a'] != y || back[y - 'a'] != x) {
                    ok = false;
                }
            }
            if (ok) total++;
        }
        return total;
    }
}

