class Solution {
    public int countSameShape(String[] words, String pattern) {
        int[] target = shape(pattern);
        int total = 0;
        for (String w : words) if (Arrays.equals(shape(w), target)) total++;
        return total;
    }

    private int[] shape(String s) {
        int[] first = new int[26];
        Arrays.fill(first, -1);
        int[] out = new int[s.length()];
        int next = 0;
        for (int i = 0; i < s.length(); i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] < 0) first[c] = next++;
            out[i] = first[c];
        }
        return out;
    }
}

