class Solution {
public:
    int countSameShape(vector<string>& words, string& pattern) {
        auto shape = [](const string& s) {
            int first[26];
            fill(first, first + 26, -1);
            vector<int> out;
            int next = 0;
            for (char ch : s) {
                if (first[ch - 'a'] < 0) first[ch - 'a'] = next++;
                out.push_back(first[ch - 'a']);
            }
            return out;
        };
        vector<int> target = shape(pattern);
        int total = 0;
        for (const string& w : words) if (shape(w) == target) total++;
        return total;
    }
};

