// Writes the shape of s into out and returns its length.
static int shape(const char* s, int* out) {
    int first[26], next = 0, n = 0;
    for (int i = 0; i < 26; i++) first[i] = -1;
    for (; s[n]; n++) {
        int c = s[n] - 'a';
        if (first[c] < 0) first[c] = next++;
        out[n] = first[c];
    }
    return n;
}

int countSameShape(char** words, int wordsSize, char* pattern) {
    int target[21], mine[21];
    int L = shape(pattern, target);
    int total = 0;
    for (int k = 0; k < wordsSize; k++) {
        int len = shape(words[k], mine);
        if (len == L && memcmp(mine, target, L * sizeof(int)) == 0) total++;
    }
    return total;
}
